{"path":"examples/extensions/truncated-tool.ts","physical_source":"examples/extensions/truncated-tool.ts","start":2508,"end":2833,"line":72,"column":6,"physical_line":72,"raw_source":"catch (err: any) {
				// ripgrep exits with 1 when no matches found
				if (err.status === 1) {
					return {
						content: [{ type: "text", text: "No matches found" }],
						details: { pattern, path: searchPath, glob, matchCount: 0 } as RgDetails,
					};
				}
				throw new Error(`ripgrep failed: ${err.message}`);
			}","raw_source_sha256":"4aa48b51b4c970c7dea8fdf1830327a45942e98189608ab7f27e0d282ee4f8f8","start_utf8_byte":2508,"end_utf8_byte":2833,"source_redacted":false}
